WITH ship_daily AS (SELECT d_ship.d_date AS ship_date, cp.cp_department AS department, cp.cp_catalog_page_number AS catalog_page_number, SUM(cs.cs_net_paid) AS daily_net_paid, SUM(cs.cs_ext_discount_amt) AS daily_discount, AVG(cs.cs_ext_ship_cost) AS avg_ship_cost, SUM(cs.cs_net_profit) AS daily_profit, COUNT(*) AS order_count, MAX(t.t_shift) AS shift FROM catalog_sales cs JOIN date_dim d_ship ON cs.cs_ship_date_sk = d_ship.d_date_sk JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk JOIN time_dim t ON cs.cs_sold_time_sk = t.t_time_sk GROUP BY d_ship.d_date, cp.cp_department, cp.cp_catalog_page_number), ship_daily_ranked AS (SELECT ship_date, department, catalog_page_number, daily_net_paid, daily_discount, avg_ship_cost, daily_profit, order_count, shift, DENSE_RANK() OVER (ORDER BY daily_profit DESC) AS profit_rank, SUM(daily_net_paid) OVER (ORDER BY ship_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_paid, CASE WHEN daily_discount > 5000 THEN 'Very High Discount' WHEN daily_discount > 2000 THEN 'High Discount' WHEN daily_discount > 0 THEN 'Moderate Discount' ELSE 'No Discount' END AS discount_category FROM ship_daily) SELECT ship_date, department, catalog_page_number, daily_net_paid, daily_discount, avg_ship_cost, daily_profit, order_count, shift, profit_rank, cumulative_net_paid, discount_category FROM ship_daily_ranked WHERE profit_rank <= 5 ORDER BY ship_date DESC
